// Validate inputs to the LLM router
const input = $input.first().json;

const validProviders = ['ollama', 'gemini', 'claude', 'chatgpt'];
const validFormats = ['text', 'json'];

const errors = [];
if (!validProviders.includes(input.provider)) {
  errors.push(`provider "${input.provider}" not in ${validProviders.join(', ')}`);
}
if (!input.system_prompt || typeof input.system_prompt !== 'string') {
  errors.push('system_prompt missing or not a string');
}
if (!input.user_message || typeof input.user_message !== 'string') {
  errors.push('user_message missing or not a string');
}

const responseFormat = input.response_format || 'text';
if (!validFormats.includes(responseFormat)) {
  errors.push(`response_format "${responseFormat}" not in ${validFormats.join(', ')}`);
}

if (errors.length > 0) {
  throw new Error(
    `[article_id=${input.article_id || 'UNKNOWN'}] LLM router validation failed: ${errors.join('; ')}`
  );
}

return {
  json: {
    provider: input.provider,
    system_prompt: input.system_prompt,
    user_message: input.user_message,
    response_format: responseFormat,
    article_id: input.article_id || 'UNKNOWN'
  }
};

// Normalize Ollama response to the router's standard output shape
const raw = $input.first().json;
const meta = $('Validate Code').first().json;

// Ollama bundles reasoning into eval_count, so we can't split it out.
// thinking: 0 keeps the schema consistent across providers.
const text = raw.message?.content || raw.response || raw.content || '';

const inputTokens = raw.prompt_eval_count ?? 0;
const outputTokens = raw.eval_count ?? 0;
const thinkingTokens = 0;

if (!text) {
  throw new Error(
    `[article_id=${meta.article_id}] Ollama returned empty response`
  );
}

return {
  json: {
    response: text,
    provider_used: 'ollama',
    tokens_used: {
      input: inputTokens,
      output: outputTokens,
      thinking: thinkingTokens
    },
    article_id: meta.article_id,
    response_format: meta.response_format
  }
};

// Normalize Gemini response to the router's standard output shape
const raw = $input.first().json;
const meta = $('Validate Code').first().json;

// Text extraction from nested candidates structure
const candidates = raw.candidates || [];
const firstCandidate = candidates[0] || {};
const parts = firstCandidate.content?.parts || [];
const text = parts.map(p => p.text || '').join('').trim();

// Token counts
const usage = raw.usageMetadata || {};
const inputTokens = usage.promptTokenCount ?? 0;
const outputTokens = usage.candidatesTokenCount ?? 0;        // visible output
const thinkingTokens = usage.thoughtsTokenCount ?? 0;        // hidden reasoning

if (!text) {
  throw new Error(
    `[article_id=${meta.article_id}] Gemini returned empty response`
  );
}

return {
  json: {
    response: text,
    provider_used: 'gemini',
    tokens_used: {
      input: inputTokens,
      output: outputTokens,
      thinking: thinkingTokens
    },
    article_id: meta.article_id,
    response_format: meta.response_format
  }
};

