// Normalize Gemini response to the router's standard output shape
const raw = $input.first().json;
const meta = $('Validate Code').first().json;

// Text extraction from nested candidates structure
const candidates = raw.candidates || [];
const firstCandidate = candidates[0] || {};
const parts = firstCandidate.content?.parts || [];
const text = parts.map(p => p.text || '').join('').trim();

// Token counts
const usage = raw.usageMetadata || {};
const inputTokens = usage.promptTokenCount ?? 0;
const outputTokens = usage.candidatesTokenCount ?? 0;        // visible output
const thinkingTokens = usage.thoughtsTokenCount ?? 0;        // hidden reasoning

if (!text) {
  throw new Error(
    `[article_id=${meta.article_id}] Gemini returned empty response`
  );
}

return {
  json: {
    response: text,
    provider_used: 'gemini',
    tokens_used: {
      input: inputTokens,
      output: outputTokens,
      thinking: thinkingTokens
    },
    article_id: meta.article_id,
    response_format: meta.response_format
  }
};

// If response_format is "json", parse the response string into an object.
// Otherwise pass through unchanged.
const data = $input.first().json;

if (data.response_format !== 'json') {
  return { json: data };
}

let cleaned = String(data.response).trim();

// Strip code fences (triple backticks, with or without "json" tag)
cleaned = cleaned.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();

// Strip single backticks (inline code style)
if (cleaned.startsWith('`') && cleaned.endsWith('`')) {
  cleaned = cleaned.slice(1, -1).trim();
}

// If the LLM returned prose before/after the JSON, extract the first {...} or [...] block
// This is a pragmatic fallback — only used if the raw string doesn't parse
function extractJsonBlock(s) {
  const firstBrace = s.search(/[\{\[]/);
  if (firstBrace === -1) return null;
  const lastBrace = Math.max(s.lastIndexOf('}'), s.lastIndexOf(']'));
  if (lastBrace <= firstBrace) return null;
  return s.slice(firstBrace, lastBrace + 1);
}

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e1) {
  // Fallback: try extracting a JSON block from within prose
  const extracted = extractJsonBlock(cleaned);
  if (extracted) {
    try {
      parsed = JSON.parse(extracted);
    } catch (e2) {
      throw new Error(
        `[article_id=${data.article_id}] Router requested JSON but provider "${data.provider_used}" returned unparseable content. Error: ${e2.message}. Raw (first 300 chars): ${cleaned.slice(0, 300)}`
      );
    }
  } else {
    throw new Error(
      `[article_id=${data.article_id}] Router requested JSON but provider "${data.provider_used}" returned unparseable content. Error: ${e1.message}. Raw (first 300 chars): ${cleaned.slice(0, 300)}`
    );
  }
}

return {
  json: {
    response: parsed,
    provider_used: data.provider_used,
    tokens_used: data.tokens_used,
    article_id: data.article_id
  }
};
